<script lang="ts">
 import {onMount,onDestroy,tick} from 'svelte';import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';
 let {blob}:{blob:Blob}=$props();let canvas:HTMLCanvasElement;let pageNumber=$state(1),pages=$state(0),busy=$state(true),error=$state('');let alive=true,document:any,task:any,renderTask:any;
 async function render(number:number){busy=true;error='';try{const page=await document.getPage(number);if(!alive)return;await tick();const base=page.getViewport({scale:1});const scale=Math.min(1.8,1100/base.width,Math.sqrt(4000000/(base.width*base.height)));const viewport=page.getViewport({scale});canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);renderTask=page.render({canvas,canvasContext:canvas.getContext('2d'),viewport});await renderTask.promise;if(alive)pageNumber=number;page.cleanup()}catch(e){if(alive)error=(e as Error).message}finally{if(alive)busy=false}}
 onMount(()=>{(async()=>{try{const pdf=await import('pdfjs-dist');if(!alive)return;pdf.GlobalWorkerOptions.workerSrc=workerUrl;const bytes=await blob.arrayBuffer();if(!alive)return;task=pdf.getDocument({data:new Uint8Array(bytes),disableFontFace:true,useSystemFonts:true,maxImageSize:32000000,cMapUrl:'/pdf-preview/cmaps/',cMapPacked:true,standardFontDataUrl:'/pdf-preview/standard_fonts/',wasmUrl:'/pdf-preview/wasm/'});document=await task.promise;if(!alive)return;pages=document.numPages;await render(1)}catch(e){if(alive){error=(e as Error).message;busy=false}}})()});
 onDestroy(()=>{alive=false;renderTask?.cancel();if(task)void task.destroy().catch(()=>{})});
</script>
<div class="pdf-view"><nav aria-label="PDF pages"><button disabled={busy||pageNumber<=1} onclick={()=>render(pageNumber-1)}>Previous page</button><span>Page {pageNumber} of {pages||'…'}</span><button disabled={busy||pageNumber>=pages} onclick={()=>render(pageNumber+1)}>Next page</button></nav>{#if busy}<p role="status">Rendering PDF…</p>{/if}{#if error}<p role="alert">Cannot preview this PDF: {error}. You can download the original.</p>{/if}<canvas bind:this={canvas} aria-label={'PDF page '+pageNumber} style:visibility={busy?'hidden':'visible'}></canvas></div>
<style>.pdf-view{min-height:100%;background:#eef2f5;padding:12px}nav{display:flex;justify-content:center;align-items:center;gap:16px;position:sticky;top:0;background:white;padding:10px;border-radius:6px;z-index:1}button{min-height:44px;border:1px solid #b6c5ce;border-radius:6px;background:white;color:#132b40;padding:8px 14px;font:inherit;cursor:pointer}button:disabled{color:#4b5563;cursor:default}canvas{display:block;max-width:100%;height:auto;margin:16px auto;background:white}p{color:#132b40}</style>
